package main

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

// lockFile pins everything one Kubernetes version's bundle is built from: the
// exact bytes of every upstream artifact, and the exact image manifests behind
// every tag kubeadm asks for.
//
// It is generated by `make lock`, reviewed as a diff, and committed. The build
// then trusts the lock rather than the upstream tags and CDNs it came from, so a
// mutable tag or a compromised mirror cannot change what ships without the
// change appearing in a pull request first.
type lockFile struct {
	Kubernetes string                  `json:"kubernetes"`
	Artifacts  map[string]lockArtifact `json:"artifacts"`
	Images     []lockImage             `json:"images"`
}

// lockArtifact is one downloaded file: where it came from and what it hashes to.
type lockArtifact struct {
	URL    string `json:"url"`
	Sha256 string `json:"sha256"`
}

// lockImage is one container image: the tag kubeadm asks for, and the
// linux/amd64 manifest digest that tag resolved to when the lock was written.
type lockImage struct {
	Ref    string `json:"ref"`
	Digest string `json:"digest"`
}

// lockPath is where the lock for one Kubernetes version lives. One file per
// version keeps a rotation to a clean diff.
func lockPath(lockDir, k8sVersion string) string {
	return filepath.Join(lockDir, k8sVersion+".json")
}

// marshalLock renders a lock as the bytes that belong in the file: map keys
// sorted by encoding/json, images sorted by reference, two-space indent, one
// trailing newline. Re-running `make lock` over unchanged upstreams therefore
// rewrites the file byte for byte.
func marshalLock(l lockFile) ([]byte, error) {
	sort.Slice(l.Images, func(i, j int) bool { return l.Images[i].Ref < l.Images[j].Ref })
	out, err := json.MarshalIndent(l, "", "  ")
	if err != nil {
		return nil, err
	}
	return append(out, '\n'), nil
}

// writeLock writes the lock for one Kubernetes version.
func writeLock(lockDir string, l lockFile) error {
	if err := os.MkdirAll(lockDir, 0o755); err != nil {
		return fmt.Errorf("create %s: %w", lockDir, err)
	}
	out, err := marshalLock(l)
	if err != nil {
		return err
	}
	path := lockPath(lockDir, l.Kubernetes)
	if err := os.WriteFile(path, out, 0o644); err != nil {
		return fmt.Errorf("write %s: %w", path, err)
	}
	return nil
}

// readLock loads the lock for one Kubernetes version. A missing lock is the
// common case worth a good message: it is what a version bump looks like before
// anyone has generated and reviewed the pins.
func readLock(lockDir, k8sVersion string) (lockFile, error) {
	path := lockPath(lockDir, k8sVersion)
	raw, err := os.ReadFile(path)
	if err != nil {
		if os.IsNotExist(err) {
			return lockFile{}, fmt.Errorf("no lock for %s: run make lock and review the diff (expected %s)", k8sVersion, path)
		}
		return lockFile{}, err
	}
	var l lockFile
	if err := json.Unmarshal(raw, &l); err != nil {
		return lockFile{}, fmt.Errorf("parse %s: %w", path, err)
	}
	if l.Kubernetes != k8sVersion {
		return lockFile{}, fmt.Errorf("%s locks %q, not %s", path, l.Kubernetes, k8sVersion)
	}
	if len(l.Artifacts) == 0 {
		return lockFile{}, fmt.Errorf("%s locks no artifacts", path)
	}
	return l, nil
}

// checkArtifactAgainstLock rejects a downloaded artifact that is not the one the
// lock describes, by URL or by content.
func checkArtifactAgainstLock(l lockFile, component, url, digest string) error {
	locked, ok := l.Artifacts[component]
	if !ok {
		return fmt.Errorf("%s is not in the lock for %s: run make lock and review the diff", component, l.Kubernetes)
	}
	if locked.URL != url {
		return fmt.Errorf("%s: the pins would download %s but the lock has %s: run make lock and review the diff",
			component, url, locked.URL)
	}
	if !strings.EqualFold(locked.Sha256, digest) {
		return fmt.Errorf("%s: downloaded %s but the lock has %s; upstream changed the bytes behind this URL",
			component, digest, locked.Sha256)
	}
	return nil
}

// checkImageListAgainstLock requires kubeadm's image list to be exactly the set
// the lock pins. Anything else means the lock was written for a different
// kubeadm, and the bundle would be missing images or carry unreviewed ones.
func checkImageListAgainstLock(l lockFile, images []string) error {
	locked := make(map[string]struct{}, len(l.Images))
	for _, img := range l.Images {
		locked[img.Ref] = struct{}{}
	}
	got := make(map[string]struct{}, len(images))
	for _, img := range images {
		got[img] = struct{}{}
	}

	var missing, unexpected []string
	for ref := range locked {
		if _, ok := got[ref]; !ok {
			missing = append(missing, ref)
		}
	}
	for ref := range got {
		if _, ok := locked[ref]; !ok {
			unexpected = append(unexpected, ref)
		}
	}
	if len(missing) == 0 && len(unexpected) == 0 {
		return nil
	}
	sort.Strings(missing)
	sort.Strings(unexpected)

	var b strings.Builder
	fmt.Fprintf(&b, "kubeadm's image list does not match the lock for %s", l.Kubernetes)
	for _, ref := range missing {
		fmt.Fprintf(&b, "\n  - %s (in the lock, not requested by kubeadm)", ref)
	}
	for _, ref := range unexpected {
		fmt.Fprintf(&b, "\n  + %s (requested by kubeadm, not in the lock)", ref)
	}
	b.WriteString("\nrun make lock and review the diff")
	return fmt.Errorf("%s", b.String())
}

// summarizeLockChange describes a regenerated lock against the one on disk, so
// `make lock` says what a reviewer is about to be asked to approve.
func summarizeLockChange(old, updated lockFile) []string {
	var lines []string
	for _, component := range sortedKeys(updated.Artifacts) {
		now := updated.Artifacts[component]
		before, ok := old.Artifacts[component]
		if !ok {
			lines = append(lines, fmt.Sprintf("+ artifact %s %s", component, now.URL))
			continue
		}
		// A pin bump can move both the URL and the bytes behind it at once; report
		// each change on its own line rather than only the first one noticed.
		if before.URL != now.URL {
			lines = append(lines, fmt.Sprintf("~ artifact %s url %s -> %s", component, before.URL, now.URL))
		}
		if !strings.EqualFold(before.Sha256, now.Sha256) {
			lines = append(lines, fmt.Sprintf("~ artifact %s sha256 %s -> %s", component, before.Sha256, now.Sha256))
		}
	}
	for _, component := range sortedKeys(old.Artifacts) {
		if _, ok := updated.Artifacts[component]; !ok {
			lines = append(lines, fmt.Sprintf("- artifact %s", component))
		}
	}

	oldImages := make(map[string]string, len(old.Images))
	for _, img := range old.Images {
		oldImages[img.Ref] = img.Digest
	}
	newImages := make(map[string]string, len(updated.Images))
	for _, img := range updated.Images {
		newImages[img.Ref] = img.Digest
	}
	for _, ref := range sortedKeys(newImages) {
		before, ok := oldImages[ref]
		switch {
		case !ok:
			lines = append(lines, fmt.Sprintf("+ image %s %s", ref, newImages[ref]))
		case before != newImages[ref]:
			lines = append(lines, fmt.Sprintf("~ image %s %s -> %s", ref, before, newImages[ref]))
		}
	}
	for _, ref := range sortedKeys(oldImages) {
		if _, ok := newImages[ref]; !ok {
			lines = append(lines, fmt.Sprintf("- image %s", ref))
		}
	}
	return lines
}

// sortedKeys returns a map's keys in order, so output is deterministic.
func sortedKeys[V any](m map[string]V) []string {
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	return keys
}
